// Bundles CHANGELOG.md for the phone's What's new screen (it can't import ?raw files). Run after
// editing the changelog; src/shared.test.ts fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";

export const OUT = "mobile/src/changelog.ts";

// The phone's first release is v1.2.0 (PLAN D257): desktop-only history before it stays out.
const phoneSections = (md) => ((i) => (i < 0 ? md : md.slice(0, i + 1)))(md.search(/\n## v(0\.|1\.[01]\.)/));

export const render = () => `// Generated by scripts/mobile-changelog.mjs from CHANGELOG.md. Do not edit.\nexport const CHANGELOG = ${JSON.stringify(phoneSections(readFileSync("CHANGELOG.md", "utf8").replace(/\r\n/g, "\n")))};\n`;

if (process.argv[1]?.endsWith("mobile-changelog.mjs")) {
  writeFileSync(OUT, render());
  console.log(`Wrote ${OUT}`);
}
